# e = a y² + b y + c, as Hamblin's GEORGE is usually quoted. Reading a, b,
# c and y and punching e are ours.
R (a) ; R (b) ; R (c) ; R (y) ;
a y dup × × b y × + c + (e) (P) ;

# Five iterations of x = (x + y/x)/2 from 1: "Newton's method for the
# square root of y". Manual, section 1.6, page 6. Setting y and punching
# the result are ours.
2 (y) ;
1, 1, 5 rep (a) dup y rev ÷ + 2 ÷ ]
(P) ;

# Section 1.8, page 10: iterate x = (x + y/x)/2 from unity "until
# successive values differ by not more than e". The result is left in the
# accumulator. Setting y and e and punching the result are ours.
2 (y) ; .00001 (e) ;
1 * 0 (x) y x ÷ + 2 ÷ dup x - mod e > 0 ↑
(P) ;
